import{_ as o,o as r,c as a,a3 as e}from"./chunks/framework.qCVWde4n.js";const g=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":null}'),d={name:"faq.md"};function s(n,t,l,i,c,h){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><p>按「你现在遇到什么」来找答案。</p><h2 id="装了没反应" tabindex="-1">装了没反应 <a class="header-anchor" href="#装了没反应" aria-label="Permalink to &quot;装了没反应&quot;">​</a></h2><p><strong>Q：我改了参数 / 装了 Mod，进游戏发现没变化。</strong></p><p>A：九成是<strong>没重开游戏</strong>。框架只在启动时扫描一次 Mod 目录、读一次参数。改完必须<strong>完全退出游戏</strong>（不是切后台，是彻底关掉）再重开。</p><p>如果重开了还是没反应，按顺序查：</p><ol><li>「Mod」页能不能看到你的 Mod？（看不到 = 位置放错了）</li><li><code>mod.json</code> 是不是<strong>直接丢在 <code>mods/</code> 根目录</strong>了？（必须放在<strong>子文件夹</strong>里）</li><li>文件夹名是不是 <code>_</code> 开头？（<code>_</code> 是系统保留前缀，会被跳过）</li><li>「日志」页有没有相关错误？</li></ol><h2 id="悬浮窗「小u」找不到-点不动" tabindex="-1">悬浮窗「小u」找不到 / 点不动 <a class="header-anchor" href="#悬浮窗「小u」找不到-点不动" aria-label="Permalink to &quot;悬浮窗「小u」找不到 / 点不动&quot;">​</a></h2><p><strong>Q：屏幕上找不到「小u」，或者点了没反应。</strong></p><p>A：</p><ul><li>可能被<strong>收起成小圆点</strong>了（半透明、很小）。在屏幕边缘找找，点圆点还原。</li><li><strong>三指同时按住屏幕</strong>可以强制唤起（这是为「部分机型收不到抬手事件」留的逃生通道）。</li><li>桌面端可以直接按 <strong>F9</strong> 开关面板。</li></ul><h2 id="数值不对劲" tabindex="-1">数值不对劲 <a class="header-anchor" href="#数值不对劲" aria-label="Permalink to &quot;数值不对劲&quot;">​</a></h2><p><strong>Q：感觉伤害/速度/什么的都变快了，像开了加速。</strong></p><p>A：先看「<strong>状态</strong>」页的「<strong>偏离原版的参数</strong>」清单——它列出所有当前值 ≠ 默认值的参数。</p><p>重点怀疑 <code>sandbox.timeScale</code>（游戏倍速）。<strong>倍速参数不会跨重启保留</strong>，启动时强制回 <code>1.0</code>，所以正常重开一次就好了。</p><h2 id="面板看不懂-按钮太多" tabindex="-1">面板看不懂 / 按钮太多 <a class="header-anchor" href="#面板看不懂-按钮太多" aria-label="Permalink to &quot;面板看不懂 / 按钮太多&quot;">​</a></h2><p><strong>Q：控制台里一堆选项，不知道该动哪个。</strong></p><p>A：打开「小u」→「<strong>帮助</strong>」页。那里是<strong>大白话、零英文术语</strong>的说明。首次安装会<strong>自动弹一次</strong>。</p><p>日常想快速上手：参数页 → 选一个「一键预设」（原版 / 硬核 / 爽快 / 快节奏）。</p><h2 id="模型没生效" tabindex="-1">模型没生效 <a class="header-anchor" href="#模型没生效" aria-label="Permalink to &quot;模型没生效&quot;">​</a></h2><p><strong>Q：我做了自制模型，但船还是原版的样子 / 看不见。</strong></p><p>A：按顺序查：</p><ol><li>AssetBundle 是不是用 <code>UncompressedAssetBundle</code> <strong>不压缩</strong>打的？（压缩包读不了）</li><li>文件放对了吗？<code>mods/我的Mod/models/xxx.unity3d</code></li><li><code>model</code> 写法对不对？<code>&quot;@包别名:资产名&quot;</code></li><li>「Mod」页底部有<strong>模型自检</strong>，看文件在不在、有没有加载成功</li><li>「日志」页看有没有加载失败的具体原因</li></ol><h2 id="mod-之间打架了" tabindex="-1">Mod 之间打架了 <a class="header-anchor" href="#mod-之间打架了" aria-label="Permalink to &quot;Mod 之间打架了&quot;">​</a></h2><p><strong>Q：装了两个 Mod，好像互相覆盖。</strong></p><p>A：这是<strong>正常现象</strong>。「Mod」页顶部会显示「检测到 N 处 Mod 间重名冲突」，点「日志」页能看到每条具体是哪两个 Mod。<strong>后加载的覆盖先加载的</strong>。</p><p>想控制谁赢：在 <code>mod.json</code> 里调 <code>priority</code>（越小越先加载）。详见 <a href="/AtlanticFleetSite/docs/use/conflicts">Mod 冲突排查</a>。</p><h2 id="战斗里「点了发射就没反应」" tabindex="-1">战斗里「点了发射就没反应」 <a class="header-anchor" href="#战斗里「点了发射就没反应」" aria-label="Permalink to &quot;战斗里「点了发射就没反应」&quot;">​</a></h2><p><strong>Q：点发射按钮，然后什么都没发生。</strong></p><p>A：<strong>先看一眼当前倍速</strong>。如果倍速不是 <code>x1</code>，先点回 <code>x1</code> 再试。</p><p>原因是 <code>Time.timeScale</code> 会同时管辖开火动画、装填、AI 行动、转场——倍速很高时，动画飞快推进，观感就像「一瞬间什么都没了」。</p><p>如果 x1 下<strong>依然</strong>异常，那就是真缺陷，请导出日志（「日志」页 →「复制全部日志」）反馈。</p><h2 id="分享码怎么用" tabindex="-1">分享码怎么用 <a class="header-anchor" href="#分享码怎么用" aria-label="Permalink to &quot;分享码怎么用&quot;">​</a></h2><p><strong>Q：别人发了我一串 <code>AFMOD1:...</code>，怎么装？</strong></p><p>A：</p><ul><li>在游戏内：「小u」→「参数」页 →「<strong>粘贴导入分享码</strong>」→ 重开游戏</li><li>或粘进仓库网页的<strong>分享码解析器</strong>，先看清楚这是什么再决定装不装</li></ul><h2 id="不支持联网对战" tabindex="-1">不支持联网对战？ <a class="header-anchor" href="#不支持联网对战" aria-label="Permalink to &quot;不支持联网对战？&quot;">​</a></h2><p><strong>Q：能和好友联网打吗？</strong></p><p>A：<strong>不支持互联网联机</strong>。本游戏本体零网络代码，且这个框架是纯客户端重编译出来的，没法做服务器。</p><p>能做的是<strong>同设备热座对战</strong>——一台手机上两个人轮流操作（<code>local.versus</code> 开关）。详见 <a href="/AtlanticFleetSite/docs/features/profile">玩家档案与本地热座</a>。</p><h2 id="怎么彻底还原" tabindex="-1">怎么彻底还原 <a class="header-anchor" href="#怎么彻底还原" aria-label="Permalink to &quot;怎么彻底还原&quot;">​</a></h2><p><strong>Q：我想把一切恢复成原版。</strong></p><p>A：分三层，看你要还原到什么程度：</p><table tabindex="0"><thead><tr><th>想要的效果</th><th>操作</th></tr></thead><tbody><tr><td>清掉所有参数改动</td><td>「参数」页 →「恢复默认」（两段确认）</td></tr><tr><td>停用 / 删除某个 Mod</td><td>「Mod」页 → 禁用或删除</td></tr><tr><td>重置整个 Mod 系统（<strong>保留</strong>自制 Mod）</td><td>「Mod」页底部 →「重置整个 Mod 系统」</td></tr><tr><td>完全回到没有框架的原版</td><td>卸载框架 APK，装回原版</td></tr></tbody></table><h2 id="日志在哪-怎么给作者看" tabindex="-1">日志在哪 / 怎么给作者看 <a class="header-anchor" href="#日志在哪-怎么给作者看" aria-label="Permalink to &quot;日志在哪 / 怎么给作者看&quot;">​</a></h2><p><strong>Q：出问题了要我提供日志，日志在哪？</strong></p><p>A：「小u」→「<strong>日志</strong>」页 →「<strong>复制全部日志</strong>」，直接粘贴发给作者即可。</p><p>日志同时落盘在 <code>&lt;ModRoot&gt;/AFMOD_log.txt</code>，游戏关掉也不会丢。</p><h2 id="还没解决" tabindex="-1">还没解决？ <a class="header-anchor" href="#还没解决" aria-label="Permalink to &quot;还没解决？&quot;">​</a></h2><ul><li>具体操作 → <a href="/AtlanticFleetSite/docs/use/panel">使用指南</a></li><li>排查流程 → <a href="/AtlanticFleetSite/docs/use/troubleshooting">出问题了怎么查</a></li><li>技术原理 → <a href="/AtlanticFleetSite/docs/technical">技术细节</a></li></ul><h2 id="还是搞不定-直接来问" tabindex="-1">还是搞不定？直接来问 <a class="header-anchor" href="#还是搞不定-直接来问" aria-label="Permalink to &quot;还是搞不定？直接来问&quot;">​</a></h2><table tabindex="0"><thead><tr><th>想做什么</th><th>去哪</th></tr></thead><tbody><tr><td>提问 / 反馈 / 找人一起玩</td><td><strong>QQ 群 <a href="https://qm.qq.com/cgi-bin/qm/qr?group_code=957336473" target="_blank" rel="noreferrer"><code>957336473</code></a></strong>（点群号直接进）</td></tr><tr><td>看开发进展与视频</td><td><a href="https://space.bilibili.com/434094293" target="_blank" rel="noreferrer">B 站主页</a>（UID 434094293）</td></tr><tr><td>找现成的 Mod</td><td><a href="https://atlanticfleet.asia/mods/" target="_blank" rel="noreferrer">Mod 仓库</a></td></tr><tr><td>投稿自己的 Mod</td><td><a href="/AtlanticFleetSite/docs/repo/publish">上传你的 Mod</a></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">提问前顺手做一件事</p><p>把「小u」→「日志」页的日志复制一份贴上来，作者几乎能立刻定位问题。</p></div>',53)])])}const u=o(d,[["render",s]]);export{g as __pageData,u as default};
